INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a1','东山再起','dong-shan-zai-qi','dōng shān zài qǐ','比喻失势或退隐后重新恢复地位、取得成功。','重新复出并取得成就。','谢安早年隐居东山，朝廷屡次征召后出仕，最终建立功业。','适合表达经历低谷、退出或失势后重新取得成功。','东山再起 比喻失势或退隐后重新恢复地位、取得成功。 重新复出并取得成就。 适合表达经历低谷、退出或失势后重新取得成功。 失败后复出','published',1,unixepoch(),unixepoch(),unixepoch());
