INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a2','破釜沉舟','po-fu-chen-zhou','pò fǔ chén zhōu','比喻下定决心、不留退路地奋战到底。','以断绝退路表示必胜的决心。','项羽渡过漳河后命令砸锅沉船，只带数日粮食，激励将士决战。','用于形容为达成目标而断绝退路、全力以赴。','破釜沉舟 比喻下定决心、不留退路地奋战到底。 以断绝退路表示必胜的决心。 用于形容为达成目标而断绝退路、全力以赴。 背水一战','published',1,unixepoch(),unixepoch(),unixepoch());
