INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a3','投笔从戎','tou-bi-cong-rong','tóu bǐ cóng róng','指文人放弃文职，投身军旅、建功边疆。','放下笔墨参加军队。','班超不甘长期替官府抄写文书，投身军旅并出使西域。','用于表达弃文从武或转换道路、追求更大功业。','投笔从戎 指文人放弃文职，投身军旅、建功边疆。 放下笔墨参加军队。 用于表达弃文从武或转换道路、追求更大功业。 改变志向','published',1,unixepoch(),unixepoch(),unixepoch());
