INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a4','洛阳纸贵','luo-yang-zhi-gui','luò yáng zhǐ guì','形容作品广受欢迎，风行一时。','作品流传甚广，受到热烈欢迎。','左思写成《三都赋》后，洛阳人竞相传抄，一时纸价上涨。','适合赞誉文章、著作流传广泛、影响巨大。','洛阳纸贵 形容作品广受欢迎，风行一时。 作品流传甚广，受到热烈欢迎。 适合赞誉文章、著作流传广泛、影响巨大。 作品风行','published',1,unixepoch(),unixepoch(),unixepoch());
