INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a5','卧薪尝胆','wo-xin-chang-dan','wò xīn cháng dǎn','形容刻苦自励，发愤图强。','忍受艰苦，提醒自己不忘目标。','越王勾践战败后忍辱负重，以柴薪和苦胆警醒自己，最终复国。','用于表达在挫折后忍耐奋发、长期准备。','卧薪尝胆 形容刻苦自励，发愤图强。 忍受艰苦，提醒自己不忘目标。 用于表达在挫折后忍耐奋发、长期准备。 忍辱奋发','published',1,unixepoch(),unixepoch(),unixepoch());
