INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a6','纸上谈兵','zhi-shang-tan-bing','zhǐ shàng tán bīng','比喻只会空谈理论，不能解决实际问题。','脱离实际地空谈理论。','赵括熟读兵书却缺少实战经验，长平之战中导致赵军惨败。','常用于批评脱离现实、缺乏实践的议论或方案。','纸上谈兵 比喻只会空谈理论，不能解决实际问题。 脱离实际地空谈理论。 常用于批评脱离现实、缺乏实践的议论或方案。 批评空谈','published',1,unixepoch(),unixepoch(),unixepoch());
