INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a7','四面楚歌','si-mian-chu-ge','sì miàn chǔ gē','比喻陷入四面受敌、孤立无援的困境。','四周都是敌对力量，处境孤立。','项羽被围垓下，夜闻汉军四面唱楚歌，以为楚地尽失。','用于形容受到各方压力、缺少援助的艰难处境。','四面楚歌 比喻陷入四面受敌、孤立无援的困境。 四周都是敌对力量，处境孤立。 用于形容受到各方压力、缺少援助的艰难处境。 孤立无援','published',1,unixepoch(),unixepoch(),unixepoch());
