INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a8','完璧归赵','wan-bi-gui-zhao','wán bì guī zhào','比喻把原物完整无损地归还本人。','将物品完整地交还原主。','蔺相如奉和氏璧出使秦国，以勇气和智慧保全宝玉并送回赵国。','用于承诺或说明把借来的珍贵物品完整归还。','完璧归赵 比喻把原物完整无损地归还本人。 将物品完整地交还原主。 用于承诺或说明把借来的珍贵物品完整归还。 物归原主','published',1,unixepoch(),unixepoch(),unixepoch());
