INSERT OR IGNORE INTO allusion_origins(id,title,slug,classical_text,vernacular_story,story_dynasty,story_period,note,status,created_at,updated_at) VALUES('o-qibu','曹植七步成诗','cao-zhi-qi-bu-cheng-shi','文帝尝令东阿王七步中作诗，不成者行大法。应声便为诗曰：“煮豆持作羹，漉菽以为汁。萁在釜下燃，豆在釜中泣。本自同根生，相煎何太急。”帝深有惭色。','曹丕命弟弟曹植在七步之内作诗，否则将施以重刑。曹植随即借同根的豆与豆萁互相煎熬，写成诗讽喻兄弟相迫，曹丕听后十分惭愧。','三国','魏文帝时期','流传的四句《七步诗》为后世修改本，应与《世说新语》所载六句版本分开著录。','published',unixepoch(),unixepoch());
INSERT OR IGNORE INTO origin_sources(id,origin_id,work_id,source_type,chapter,original_text,translation,note,reference_note,sort_order,created_at,updated_at) VALUES('os-qibu-primary','o-qibu','w-shishuo','primary','文学',NULL,NULL,NULL,'南朝宋刘义庆《世说新语·文学》',0,unixepoch(),unixepoch());
INSERT OR IGNORE INTO origin_sources(id,origin_id,work_id,source_type,chapter,original_text,translation,note,reference_note,sort_order,created_at,updated_at) VALUES('os-qibu-transmission','o-qibu','w-mansou','transmission',NULL,'煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急。',NULL,'后世流传的四句版本。','宋佚名《漫叟诗话》',1,unixepoch(),unixepoch());
INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,frequency_level,frequency_note,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a-qibushi','七步诗','qi-bu-shi','qī bù shī','称誉文思敏捷、才气过人。','指曹植在七步内成诗的才思，后用来称誉文思敏捷。','','多用于赞誉他人才思敏捷。',4,'编辑初评；待语料统计校准。','七步诗 文思敏捷 才气过人 曹植 七步成诗','published',2,unixepoch(),unixepoch(),unixepoch());
INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,frequency_level,frequency_note,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a-qibucai','七步才','qi-bu-cai','qī bù cái','称誉下笔迅速、才华出众。','指如曹植七步成诗一般的敏捷才思。','','可作名词性赞语。',3,'编辑初评；待语料统计校准。','七步才 文思敏捷 才华 曹植','published',2,unixepoch(),unixepoch(),unixepoch());
INSERT OR IGNORE INTO allusions(id,title,slug,pinyin,summary,meaning,story,usage_notes,frequency_level,frequency_note,search_text,status,quality_level,created_at,updated_at,published_at) VALUES('a-chensiqibu','陈思七步','chen-si-qi-bu','chén sī qī bù','借曹植七步成诗称誉才思敏捷。','陈思指谥号陈思王的曹植；此语称誉高才。','','多见于古典书面语。',1,'古典文献用例较少；待语料统计校准。','陈思七步 曹植 陈思王 文思敏捷','published',2,unixepoch(),unixepoch(),unixepoch());
